#include "OBD.h"
namespace injector_diagnostic {OBD::OBD(std::shared_ptr<ICommunication> c):communication_(std::move(c)){}bool OBD::connect(){return communication_&&communication_->open();}void OBD::disconnect()noexcept{if(communication_)communication_->close();}bool OBD::isConnected()const noexcept{return communication_&&communication_->isOpen();}std::vector<std::string> OBD::readDtcCodes(){return simulatedDtcs_;}bool OBD::clearDtc(){if(!isConnected())return false;simulatedDtcs_.clear();return true;}std::string OBD::pidName(ObdPid p)const{switch(p){case ObdPid::EngineRpm:return "Engine RPM";case ObdPid::CoolantTemperature:return "Coolant Temperature";case ObdPid::ThrottlePosition:return "Throttle Position";case ObdPid::Map:return "MAP";case ObdPid::Maf:return "MAF";case ObdPid::O2Sensor:return "O2 Sensor";case ObdPid::ControlModuleVoltage:return "Control Module Voltage";}return "Unknown PID";}}
